// newProgressAPI builds a handler over a fresh store with one library, and
// returns the router, the store, and the library id tests seed items into.
func newProgressAPI(t *testing.T) (http.Handler, *store.Store, int64) {
	t.Helper()
	h, st := newLibraryAPI(t)
	id, err := st.CreateLibrary(context.Background(), "tv", "/media/progress", "TV")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	return h, st, id
}

