// TestProgressPut covers the write happy path (web-ui-phase-3 2.2): a valid
// body against a known item upserts and returns 200 with the stored position
// and stamp; a follow-up negative write is 400 and leaves the stored value
// untouched.
func TestProgressPut(t *testing.T) {
	h, st, libID := newProgressAPI(t)
	itemID := "itm_p1"
	seedItem(t, st, libID, "p1", "P S01E01.mkv")

	resp := putProgressBody(t, h, itemID, `{"position_seconds": 3720}`)
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusOK)
	}
	var pr progressDTO
	if err := json.NewDecoder(resp.Body).Decode(&pr); err != nil {
		t.Fatalf("decode progressDTO: %v", err)
	}
	if pr.ItemID != itemID || pr.PositionSeconds != 3720 {
		t.Fatalf("DTO = %+v, want item_id %s position 3720", pr, itemID)
	}
	if _, err := time.Parse(time.RFC3339, pr.UpdatedAt); err != nil {
		t.Fatalf("updated_at %q is not RFC3339: %v", pr.UpdatedAt, err)
	}

	// The rejected negative write must leave the stored value untouched.
	badResp := putProgressBody(t, h, itemID, `{"position_seconds": -5}`)
	defer badResp.Body.Close()
	if badResp.StatusCode != http.StatusBadRequest {
		t.Fatalf("negative write status = %d, want %d", badResp.StatusCode, http.StatusBadRequest)
	}
	if eb := decodeError(t, badResp); eb.Error.Code != "bad_request" || eb.Error.Retryable {
		t.Fatalf("error body = %+v, want bad_request/non-retryable", eb.Error)
	}
	getResp := doRequest(t, h, http.MethodGet, "/api/v1/progress/"+itemID, "", adminToken)
	defer getResp.Body.Close()
	var after progressDTO
	if err := json.NewDecoder(getResp.Body).Decode(&after); err != nil {
		t.Fatalf("decode after: %v", err)
	}
	if after.PositionSeconds != 3720 {
		t.Fatalf("position after rejected write = %d, want 3720 (untouched)", after.PositionSeconds)
	}
}

// TestPutProgressValidation is the write-endpoint rejection table (2.2):
// negative, non-integer, and non-canonical bodies are 400 bad_request; a valid
// body against an unknown item is 404 not_found.
func TestPutProgressValidation(t *testing.T) {
	h, st, libID := newProgressAPI(t)
	seedItem(t, st, libID, "val", "V.mkv")

	cases := []struct {
		name string
		item string
		body string
	}{
		{"negative", "itm_val", `{"position_seconds": -1}`},
		{"float", "itm_val", `{"position_seconds": 1.5}`},
		{"string_value", "itm_val", `{"position_seconds": "90"}`},
		{"missing_field", "itm_val", `{}`},
		{"malformed_json", "itm_val", `not json`},
		{"unknown_item", "itm_nope", `{"position_seconds": 10}`},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			resp := putProgressBody(t, h, tc.item, tc.body)
			defer resp.Body.Close()
			want := http.StatusBadRequest
			if tc.name == "unknown_item" {
				want = http.StatusNotFound
			}
			if resp.StatusCode != want {
				t.Fatalf("status = %d, want %d", resp.StatusCode, want)
			}
			eb := decodeError(t, resp)
			wantCode := "bad_request"
			if tc.name == "unknown_item" {
				wantCode = "not_found"
			}
			if eb.Error.Code != wantCode {
				t.Fatalf("error code = %q, want %q", eb.Error.Code, wantCode)
			}
		})
	}
}

// TestProgressListEndpoint covers the read endpoints (2.3): three items with
// positive positions list newest-first; an item without a record is absent
// from the list and 404s on its single-item route; limit=abc is 400.
func TestProgressListEndpoint(t *testing.T) {
	h, st, libID := newProgressAPI(t)
	ctx := context.Background()

	// Write order c → a → b so newest-first is b, a, c.
	files := []string{"c", "a", "b"}
	ids := make([]string, len(files))
	for i, f := range files {
		seedItem(t, st, libID, "list"+f, "L"+f+".mkv")
		ids[i] = "itm_list" + f
	}
	for _, id := range ids {
		if _, err := st.PutProgress(ctx, id, 100); err != nil {
			t.Fatalf("PutProgress %s: %v", id, err)
		}
		time.Sleep(2 * time.Millisecond) // strictly later updated_at per write
	}
	noRecord := "itm_norecord"
	seedItem(t, st, libID, "norecord", "N.mkv")

	t.Run("newest_first_without_record", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/progress", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusOK)
		}
		var lr progressListResponse
		if err := json.NewDecoder(resp.Body).Decode(&lr); err != nil {
			t.Fatalf("decode progressListResponse: %v", err)
		}
		want := []string{"itm_listb", "itm_lista", "itm_listc"}
		if len(lr.Items) != len(want) {
			t.Fatalf("items = %+v, want %v", lr.Items, want)
		}
		for i, id := range want {
			if lr.Items[i].ItemID != id {
				t.Fatalf("items[%d] = %s, want %s (newest-first)", i, lr.Items[i].ItemID, id)
			}
		}
	})

	t.Run("missing_record_gets_404", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/progress/"+noRecord, "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusNotFound {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusNotFound)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "not_found" {
			t.Fatalf("error code = %q, want not_found", eb.Error.Code)
		}
	})

	t.Run("non_integer_limit_400", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/progress?limit=abc", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusBadRequest {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusBadRequest)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "bad_request" {
			t.Fatalf("error code = %q, want bad_request", eb.Error.Code)
		}
	})
}

// TestListProgressLimit covers the ?limit contract (2.3): default 20, clamp to
// max 100, non-positive is 400.
func TestListProgressLimit(t *testing.T) {
	h, st, libID := newProgressAPI(t)

	// 105 positive rows: enough to distinguish the default (20), an explicit
	// page (30), and the clamp (100) without relying on silent fallbacks.
	for i := 0; i < 105; i++ {
		fileID := fmt.Sprintf("lim%03d", i)
		seedItem(t, st, libID, fileID, fileID+".mkv")
		if _, err := st.PutProgress(context.Background(), "itm_"+fileID, int64(i+1)); err != nil {
			t.Fatalf("PutProgress %s: %v", fileID, err)
		}
	}

	t.Run("default_20", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/progress", "", adminToken)
		defer resp.Body.Close()
		var lr progressListResponse
		if err := json.NewDecoder(resp.Body).Decode(&lr); err != nil {
			t.Fatalf("decode: %v", err)
		}
		if len(lr.Items) != 20 {
			t.Fatalf("default page = %d rows, want 20", len(lr.Items))
		}
	})

	t.Run("explicit_30", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/progress?limit=30", "", adminToken)
		defer resp.Body.Close()
		var lr progressListResponse
		if err := json.NewDecoder(resp.Body).Decode(&lr); err != nil {
			t.Fatalf("decode: %v", err)
		}
		if len(lr.Items) != 30 {
			t.Fatalf("limit=30 page = %d rows, want 30", len(lr.Items))
		}
	})

	t.Run("clamped_to_100", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/progress?limit=500", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want %d (clamp, not reject)", resp.StatusCode, http.StatusOK)
		}
		var lr progressListResponse
		if err := json.NewDecoder(resp.Body).Decode(&lr); err != nil {
			t.Fatalf("decode: %v", err)
		}
		if len(lr.Items) != 100 {
			t.Fatalf("limit=500 page = %d rows, want 100 (max clamp)", len(lr.Items))
		}
	})

	t.Run("zero_400", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/progress?limit=0", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusBadRequest {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusBadRequest)
		}
	})
}
